import { examples } from './demo-data.js';
import { mountGalaxy } from './galaxy.js';
let galaxy = null;

const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const majors = ['计算机类','工学类','经济与管理','人文社科','医学与健康','教育学','艺术设计','理学','农学','其他'];
const tiers = ['普通本科','双一流','高职专科','其他'];
const regions = ['华东','华北','华中','华南','西南','西北','东北','港澳台','海外'];
const statuses = ['就业','升学','待业','备考','自由职业','创业','职业中断'];
const salaries = ['不愿透露','暂无工资','5k以下','5–8k','8–12k','12–18k','18–25k','25k以上'];
let live = false, user = null, records = [], csrf = '', pageVersion = 0;
const main = $('#main');
const options = (values, selected = '', all = '') => `${all ? `<option value="">${esc(all)}</option>` : ''}${values.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}`;
const select = (name,label,values,selected='',all='') => `<label class="field"><span>${label}</span><select name="${name}" aria-label="${label}">${options(values,selected,all)}</select></label>`;
const field = (name,label,placeholder='',type='text',value='',max=100) => `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" maxlength="${max}" required></label>`;
const heading = (eyebrow,title,subtitle) => `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>`;
function toast(message) { const el=$('#toast'); el.textContent=message; el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3800); }
async function api(path, method='GET', body) {
  const response = await fetch(`/api${path}`,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});
  const type=response.headers.get('content-type')||'';
  if(!type.includes('application/json')) throw new Error('服务暂时不可用，请稍后重试。');
  const data = await response.json();
  if(!response.ok) throw new Error(data.error || '操作失败，请重试。');
  return data;
}
function authNav() {
  $('#auth-nav').innerHTML = user ? `<a href="#/account">我的航程</a><button class="text-button" id="logout">退出</button>` : `<a href="#/login">登录</a><a class="btn small" href="#/contribute">分享我的经历 ↗</a>`;
  $('#logout')?.addEventListener('click',async()=>{try{await api('/logout','POST',{});user=null;csrf='';authNav();location.hash='#/';toast('已退出登录');}catch(e){toast(e.message);}});
}
function filterForm(current={}) { return `<form id="filters" class="search-panel"><div class="search-heading"><h2>找到与你相近的出发点</h2><span>不排名学校，只看真实路径</span></div><div class="filter-grid">${select('major','所学专业',majors,current.major,'全部专业')}${select('tier','学校层次',tiers,current.tier,'全部层次')}${select('region','就读地区',regions,current.region,'全部地区')}<button class="btn" type="submit">探索职业去向 <span>↗</span></button></div><div class="popular"><span>从这里开始：</span><button type="button" class="chip" data-major="计算机类">计算机类</button><button type="button" class="chip" data-major="经济与管理">经济与管理</button><button type="button" class="chip" data-major="工学类">工学类</button><span>支持就业、升学与暂时停靠的每一种选择</span></div></form>`; }
function bindFilters() {
  $('#filters')?.addEventListener('submit', e=>{e.preventDefault();const q=new URLSearchParams(new FormData(e.target));location.hash=`#/explore?${q}`;});
  document.querySelectorAll('[data-major]').forEach(b=>b.addEventListener('click',()=>{location.hash=`#/explore?major=${encodeURIComponent(b.dataset.major)}`;}));
}
function card(r) { return `<article class="path-card"><div class="card-top"><span>${esc(r.major)} · ${esc(r.year)} 届</span><span class="source">${r.source==='demo'?'虚构示例':'本人自述 · 已审核'}</span></div><h3>${esc(r.role)}</h3><div class="card-meta">${esc(r.tier)} / ${esc(r.region)} / ${esc(r.degree)}<br>${esc(r.city)} · ${esc(r.industry)} · ${esc(r.salary)}</div><div class="route-line"><span>${esc(r.major)}</span><span class="arrow">⟶</span><span>${esc(r.status)}</span></div><div class="card-bottom"><span><span class="avatar">${esc(r.alias.slice(0,1))}</span>${esc(r.alias)}</span><button class="detail-link" data-detail="${esc(r.id)}">查看航程 ↗</button></div></article>`; }
function bindDetails() {
  document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>showDetail(records.find(x=>String(x.id)===b.dataset.detail))));
}
function showDetail(r) {
  if(!r)return;
  const dialog=$('#detail-dialog');
  dialog.innerHTML=`<div class="dialog-header"><div><div class="eyebrow">CAREER JOURNEY</div><h2>${esc(r.alias)}的航程</h2></div><button class="close" aria-label="关闭详情">×</button></div><p class="card-meta">${esc(r.year)} 届 · ${esc(r.major)} · ${esc(r.tier)} · ${esc(r.region)}<br>${esc(r.city)} / ${esc(r.role)} / 税前月薪 ${esc(r.salary)}</p><div class="notice">${r.source==='demo'?'这是虚构示例，仅用于展示网站功能。':'这是一份经内容审核的本人自述，尚未进行学历或雇佣关系核验。'} 更新于 ${esc(r.updatedAt?.slice(0,10))}</div><p>${esc(r.summary)}</p><div class="timeline">${r.timeline.map(t=>`<div class="timeline-item"><small>${esc(t.year)}</small><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p></div>`).join('')}</div><h3>想留给后来者的话</h3><p class="card-meta">${esc(r.advice)}</p><a class="btn" href="#/contribute" id="detail-share">也留下我的经历 ↗</a>`;
  $('.close',dialog).onclick=()=>dialog.close();$('#detail-share').onclick=()=>dialog.close();dialog.showModal();
}
function home() {
  const samples=records.slice(0,3);
  main.innerHTML=`<section class="cosmos" aria-label="远航者星图"><canvas id="galaxy" aria-label="母星与职业航道的动态星图；也可使用下方列表探索远航者。" role="img"></canvas><div class="cosmic-vignette"></div><div class="scene-topline"><span><i></i> ACRIS DEEP SPACE NETWORK</span><span>每一束微光，都来自一次真实的出发</span></div><div class="cosmic-copy"><div class="eyebrow">FROM HOME, INTO THE UNKNOWN</div><h1>我们如此微小。<br>也能<span>照亮一条航道。</span></h1><p>从同一片土地启航，走向不同的未来。<br>把你走过的光年，留给下一位远航者。</p><div class="hero-actions"><a class="btn" href="#/explore">探索航道 <span>↗</span></a><a class="btn light" href="#/contribute">点亮我的坐标 <span>＋</span></a></div></div><aside class="flight-panel"><span class="hud-label">SIGNAL TELEMETRY / 航道信号</span><div class="signal-number"><strong id="signal-count">${records.length.toLocaleString()}</strong><span id="signal-unit">${live?'位真实远航者':'位虚构示例远航者'}</span></div><div class="signal-meter"><span id="signal-meter-bar" style="width:${Math.min(100,Math.log10(records.length+1)*25)}%"></span></div><p>一人微光，众人星河。<br>记录越多，航道越明亮。</p><div class="hud-divider"></div><div class="hud-row"><span>TIME COORDINATES</span><strong>01 / 02 / 05 / 10 LY</strong></div><p class="hud-footnote">光年为叙事坐标，1 LY 对应毕业后 1 年</p><button class="scene-toggle" id="scene-toggle">${live?'预览示例星图':'当前展示 6 条虚构示例'} <span>↗</span></button></aside><div class="beacon-info" id="beacon-info" aria-live="polite">${records.length?'将指针移向航道中的微光，发现一段航程。':'真实星图等待第一位远航者。可以先预览示例星图。'}</div><div class="scene-bottom"><span class="home-coordinate">◉ 母星 · 启航城市 <small>HOME / DEPARTURE</small></span><span>每一束光都很微小。直到我们一起出发。</span><a href="#departure-search" id="jump-to-search">向下寻找你的航道 ↓</a></div></section><div class="wrap cosmic-content"><section id="departure-search">${filterForm()}</section><div class="stats-strip"><div><strong>${records.length}</strong><span>${live?'审核后公开的职业路径':'明确标注的虚构示例'}</span></div><div><strong>1 / 2 / 5 / 10</strong><span>毕业之后，持续回望</span></div><div><strong>每一届</strong><span>都能照亮下一届的出发</span></div></div><section><div class="section-title"><div><div class="eyebrow">VOICES ACROSS THE DARK</div><h2>每束微光，都是一个人的航程。</h2><p>${live?'起点相近，未来不必相同。':'下面是虚构航程，供你体验未来的阅读方式。'}</p></div><a href="#/explore">查看全部航程 ↗</a></div><div class="cards">${samples.length?samples.map(card).join(''):'<div class="empty">这里等待第一份真实经历。<br>你的出发，可以成为下一届的坐标。<br><a href="#/contribute">点亮第一束光 ↗</a></div>'}</div></section><section class="join-banner"><div><div class="eyebrow">YOU ARE SOMEONE’S NORTH STAR</div><h2>你走过的光年，能让后来的人少一点黑暗。</h2><p>不必是一份完美履历。出发、停靠、转向，都值得被看见。</p></div><a class="btn" href="#/contribute">成为远航者 ↗</a></section><section class="how-section"><div class="section-title"><div><div class="eyebrow">PASS THE LIGHT FORWARD</div><h2>让微光，一届一届传下去。</h2></div></div><div class="steps"><div><div class="step-num">01 / DEPARTURE</div><h3>找到相近的启航坐标</h3><p>按专业、学校层次与就读地区，寻找与你背景接近的人。</p></div><div><div class="step-num">02 / VOYAGE</div><h3>把沿途的经历留下来</h3><p>不以薪资高低定义价值。每一次真实的选择，都能成为路标。</p></div><div><div class="step-num">03 / RETURN SIGNAL</div><h3>几年之后，再传回信号</h3><p>毕业后的 1、2、5、10 年，回来更新你的航程，让时间给出更完整的答案。</p></div></div></section></div>`;
  let sceneDemo=!live;
  const startScene=(data,demo)=>{
    galaxy?.destroy();
    galaxy=mountGalaxy($('#galaxy'),data,{demo,onSelect:r=>showDetail(r),onFocus:r=>{
      $('#beacon-info').textContent=r?`${r.alias} · ${r.major} → ${r.role} · 毕业后 ${Math.max(0,new Date().getFullYear()-r.year)} 年${demo?' · 虚构示例':''}`:(data.length?'将指针移向航道中的微光，发现一段航程。':'真实星图等待第一位远航者。');
    }});
    $('#signal-count').textContent=data.length.toLocaleString();$('#signal-unit').textContent=demo?'位虚构示例远航者':'位真实远航者';
    $('#signal-meter-bar').style.width=Math.min(100,Math.log10(data.length+1)*25)+'%';
  };
  startScene(records,!live);
  $('#jump-to-search').onclick=e=>{e.preventDefault();$('#departure-search').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
  $('#scene-toggle').onclick=()=>{if(!live){toast('当前为虚构示例星图，真实贡献需运行完整服务。');return;}sceneDemo=!sceneDemo;startScene(sceneDemo?examples:records,sceneDemo);$('#scene-toggle').innerHTML=sceneDemo?'回到真实星图 <span>↗</span>':'预览示例星图 <span>↗</span>';$('#beacon-info').textContent=sceneDemo?'示例预览：6 位远航者均为虚构，不计入真实数据库。':'已回到真实星图。';};
  bindFilters();bindDetails();
}
function explore(params) {
  main.innerHTML=`<div class="wrap">${heading('EXPLORE THE POSSIBILITIES','从相近的起点，看见更多可能','筛选就读背景，阅读不同的职业选择。样本展示个人经历，不代表整个专业的就业率。')}${filterForm(Object.fromEntries(params))}<div class="results-toolbar"><span id="result-count"></span><label class="field"><span class="sr-only">搜索岗位、城市或经历</span><input id="keyword" type="search" placeholder="搜索岗位、城市、关键词…" aria-label="搜索岗位、城市、关键词"></label><label class="field"><span>当前状态</span><select id="status-filter">${options(statuses,'','全部状态')}</select></label></div><div id="distribution"></div><div class="cards results-grid" id="results"></div></div>`;
  const update=()=>{
    const keyword=$('#keyword').value.trim().toLowerCase(), status=$('#status-filter').value;
    const list=records.filter(r=>['major','tier','region'].every(k=>!params.get(k)||r[k]===params.get(k))).filter(r=>!status||r.status===status).filter(r=>!keyword||[r.role,r.city,r.industry,r.summary,r.advice,r.alias].join(' ').toLowerCase().includes(keyword));
    $('#result-count').textContent=`找到 ${list.length} 条${live?'公开路径':'虚构示例'} · ${live?'本人自述，非就业统计':'仅用于体验功能'}`;
    $('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty">暂时没有匹配的路径。<br>试试放宽地区或学校层次，或清除搜索关键词。<br><a href="#/explore" id="reset-filters">重置筛选 ↗</a></div>';
    const counts=Object.entries(list.reduce((a,r)=>(a[r.status]=(a[r.status]||0)+1,a),{}));
    $('#distribution').innerHTML=list.length?`<div class="chart-list"><span class="card-meta">当前筛选样本的状态分布（${list.length} 条，${live?'自愿提交样本':'虚构示例'}）</span>${counts.map(([label,n])=>`<div class="chart-row"><span>${esc(label)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.round(n/list.length*100)}%"></div></div><span>${n} 条 / ${Math.round(n/list.length*100)}%</span></div>`).join('')}</div>`:'';bindDetails();$('#reset-filters')?.addEventListener('click',e=>{if(location.hash==='#/explore'){e.preventDefault();render();}});
  };$('#keyword').addEventListener('input',update);$('#status-filter').addEventListener('change',update);bindFilters();update();
}
function login() {
  if(user){location.hash='#/account';return;}
  main.innerHTML=`<div class="form-wrap auth-wrap">${heading('WELCOME ABOARD','欢迎回到航程','登录后，你可以提交、更新和撤回自己的职业经历。')}<div class="form-card">${!live?'<div class="notice">当前为静态演示。账号注册与登录需启动开源项目中的数据库服务。</div><a class="btn" href="#/explore">先探索示例路径 ↗</a>':'<div class="tabs"><button class="active" data-auth="login">登录</button><button data-auth="register">注册账号</button></div><form id="auth-form" class="auth-form"><div id="alias-field" hidden>'+field('alias','公开昵称','给自己起一个昵称','text','',20)+'</div>'+field('email','邮箱','you@example.com','email','',254)+field('password','密码（至少 10 位）','','password','',128)+'<p class="card-meta" id="auth-note">邮箱仅用于账号登录，不会随职业档案公开。当前尚未提供邮件验证和密码找回。</p><label class="check" id="auth-consent" hidden><input type="checkbox" name="consent">我已阅读隐私说明，同意为创建账号处理邮箱、昵称和密码摘要。</label><button class="btn" type="submit">登录</button><div class="form-message" role="alert"></div></form>'}</div></div>`;
  if(!live)return;
  let action='login';const form=$('#auth-form');form.elements.alias.required=false;form.elements.alias.disabled=true;
  document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{action=b.dataset.auth;document.querySelectorAll('[data-auth]').forEach(x=>x.classList.toggle('active',x===b));$('#alias-field').hidden=action!=='register';$('#auth-consent').hidden=action!=='register';form.elements.alias.required=action==='register';form.elements.alias.disabled=action!=='register';form.elements.consent.required=action==='register';$('button[type=submit]',form).textContent=action==='login'?'登录':'创建账号';form.elements.password.autocomplete=action==='login'?'current-password':'new-password';});
  form.onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',form);b.disabled=true;try{const data=await api('/'+action,'POST',{...Object.fromEntries(new FormData(form)),consent:form.elements.consent.checked});user=data.user;csrf=data.csrf;authNav();location.hash='#/account';toast(action==='login'?'欢迎回来':'账号创建成功');}catch(err){$('.form-message',form).textContent=err.message;}finally{b.disabled=false;}};
}
function contribution() {
  main.innerHTML=`<div class="form-wrap">${heading('LEAVE YOUR SIGNPOST','把你的经历，留给后来的人','大约花 5 分钟，记录你的出发点和第一份选择。请不要填写真实姓名、具体学校、公司名称或联系方式。')}<div class="notice">${live?'提交后进入审核队列，审核通过才会公开。学校仅记录层次和地区。':'演示模式：仅可在本浏览器保存草稿，不会提交服务器或向其他人展示。请勿填写真实个人信息。'}</div>${live&&!user?'<div class="form-card"><p>请先登录，方便你后续更新、回访或撤回记录。</p><a class="btn" href="#/login">登录 / 注册 ↗</a></div>':`<form id="contribute-form" class="form-card"><div class="form-grid">${field('alias','公开昵称','不使用真实姓名','text',user?.alias||'',20)}${select('year','毕业年份',Array.from({length:27},(_,i)=>String(2026-i)),'2025')}${select('major','专业大类',majors)}${select('degree','学历',['专科','本科','硕士','博士'])}${select('tier','学校层次',tiers)}${select('region','就读地区',regions)}${field('startCity','启航城市（毕业时所在城市）','只填写城市，如武汉','text','',30)}${field('city','目前所在城市','只填写城市，如杭州','text','',30)}${select('status','当前状态',statuses)}${field('industry','行业','如制造业、教育、待确定','text','',30)}${field('role','岗位或当前方向','如设备技术员、准备升学','text','',40)}${select('salary','税前月薪区间',salaries)}${select('followup','愿意接受后续站内回访吗？',['愿意','暂不愿意'])}<label class="field full"><span>用一句话概括你的经历（10–200 字）</span><textarea name="summary" required minlength="10" maxlength="200" placeholder="当时如何选择，现在有什么感受？"></textarea></label><label class="field full"><span>想留给后来者的建议（10–600 字）</span><textarea name="advice" required minlength="10" maxlength="600" placeholder="你希望毕业时有人告诉你什么？"></textarea></label></div><label class="check"><input type="checkbox" name="consent" required><span>我确认这是本人经历，同意将以上昵称与职业经历经审核后公开展示。我可以在“我的航程”更正或撤回。<a href="#/privacy">阅读隐私说明 ↗</a></span></label><div class="inline-actions"><button class="btn" type="submit">${live?'提交审核':'保存演示草稿'} ↗</button>${!live?'<button type="button" class="btn light" id="clear-draft">清除草稿</button>':''}</div><div class="form-message" role="alert"></div></form>`}</div>`;
  const form=$('#contribute-form');if(!form)return;
  if(!live){try{const draft=JSON.parse(localStorage.getItem('acris-demo-draft')||'null');if(draft)for(const [key,value]of Object.entries(draft))if(form.elements[key]&&key!=='consent')form.elements[key].value=value;}catch{}$('#clear-draft').onclick=()=>{try{localStorage.removeItem('acris-demo-draft');form.reset();toast('演示草稿已清除');}catch{toast('浏览器不允许访问本地存储');}};}
  form.onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',form);b.disabled=true;const data={...Object.fromEntries(new FormData(form)),year:Number(form.elements.year.value),consent:form.elements.consent.checked,followup:form.elements.followup.value==='愿意'};try{if(live){await api('/records','POST',data);toast('已提交审核，可在我的航程查看');location.hash='#/account';}else{localStorage.setItem('acris-demo-draft',JSON.stringify(data));toast('演示草稿已保存在本浏览器');}}catch(err){$('.form-message',form).textContent=err.message;}finally{b.disabled=false;}};
}
async function account(version) {
  if(!live||!user){location.hash='#/login';return;}
  main.innerHTML=`<div class="wrap article">${heading('YOUR OWN JOURNEY','我的航程','你的经历由你掌握。每次更新将重新审核，撤回或删除立即生效。')}<p>正在读取你的记录…</p></div>`;
  try{const data=await api('/mine');if(version!==pageVersion)return;
  main.innerHTML=`<div class="wrap article">${heading('YOUR OWN JOURNEY',`${esc(user.alias)}，欢迎回来`,'留下此刻的选择，也为几年后的自己保留一个坐标。')}<div class="dashboard-tools">${data.records.length?'<a class="btn" href="#/explore">探索公开路径 ↗</a>':'<a class="btn" href="#/contribute">提交一段经历 ↗</a>'}<button class="btn light" id="export-data">导出我的资料</button>${user.admin?'<a class="btn light" href="#/admin">审核工作台</a>':''}</div><div class="notice">回访节点：毕业后 1、2、5、10 年。当前提供站内到期提醒；尚未开启邮件、短信或自动抽样联系。</div><div class="dashboard-list">${data.records.length?data.records.map(r=>`<article class="dashboard-item"><span class="status-pill">${esc({pending:'待审核',approved:'已公开',rejected:'需修改',withdrawn:'已撤回'}[r.reviewStatus])}</span><h3>${esc(r.role)} · ${esc(r.city)}</h3><p>${esc(r.summary)}</p><p>审核反馈：${esc(r.reviewNote||'暂无')}<br>${r.followup?`下次回访：${esc(r.nextFollowup||'既定节点均已过，可随时更新')}${r.due?' · 已到回访时间':''}`:'你暂未选择参与回访'}</p><div class="inline-actions"><button class="btn small" data-update="${r.id}">补充回访 / 更正</button>${r.reviewStatus!=='withdrawn'?`<button class="btn light small" data-withdraw="${r.id}">撤回公开</button>`:''}<button class="btn light small danger" data-delete="${r.id}">删除记录</button></div></article>`).join(''):'<div class="empty">还没有记录。从你的第一份选择开始吧。</div>'}</div><div class="notice">奖励计划处于设计阶段，当前没有可提现余额，也没有付费订单。</div><button class="btn light small danger" id="delete-account">删除账号与全部资料</button></div>`;
  $('#export-data').onclick=async()=>{try{const d=await api('/export');const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='acris-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}};
  document.querySelectorAll('[data-update]').forEach(b=>b.onclick=()=>updateDialog(data.records.find(r=>r.id===b.dataset.update)));
  for(const [attr,method,suffix,message] of [['withdraw','POST','/withdraw','撤回后，其他人将无法查看这条记录。确认撤回？'],['delete','DELETE','','删除后无法恢复这条记录。确认删除？']])document.querySelectorAll(`[data-${attr}]`).forEach(b=>b.onclick=async()=>{if(!confirm(message))return;try{await api(`/records/${b.dataset[attr]}${suffix}`,method,{});await refresh();render();toast('操作完成');}catch(e){toast(e.message);}});
  $('#delete-account').onclick=async()=>{if(!confirm('这会永久删除账号、全部职业记录和回访，无法恢复。确认继续？'))return;const password=prompt('请输入当前密码确认删除账号：');if(!password)return;try{await api('/account','DELETE',{password});user=null;csrf='';await refresh();authNav();location.hash='#/';toast('账号和资料已删除');}catch(e){toast(e.message);}};
  }catch(e){if(version===pageVersion)main.innerHTML=`<div class="wrap article"><div class="notice">${esc(e.message)}</div><button class="btn" id="retry">重新读取</button></div>`;$('#retry')?.addEventListener('click',render);}
}
function updateDialog(r) {
  const d=$('#detail-dialog');d.innerHTML=`<div class="dialog-header"><h2>更正或补充回访</h2><button class="close" aria-label="关闭">×</button></div><p class="card-meta">每次修改会暂时下架公开记录并重新审核。回访会加入时间线；更正可以直接修改原有文字。</p><form id="update-form"><div class="form-grid">${field('alias','公开昵称','','text',r.alias,20)}${field('startCity','启航城市','','text',r.startCity||'',30)}${field('city','目前城市','','text',r.city,30)}${select('major','专业大类',majors,r.major)}${select('tier','学校层次',tiers,r.tier)}${select('region','就读地区',regions,r.region)}${select('degree','学历',['专科','本科','硕士','博士'],r.degree)}${field('year','毕业年份','','number',r.year,4)}${select('status','当前状态',statuses,r.status)}${field('industry','目前行业','','text',r.industry,30)}${field('role','目前岗位或方向','','text',r.role,40)}${select('salary','税前月薪区间',salaries,r.salary)}<label class="field full"><span>经历概括（10–200 字）</span><textarea name="summary" minlength="10" maxlength="200" required>${esc(r.summary)}</textarea></label><label class="field full"><span>建议（10–600 字）</span><textarea name="advice" minlength="10" maxlength="600" required>${esc(r.advice)}</textarea></label><div class="full"><h3>更正已有时间线</h3><p class="card-meta">修改对应阶段的文字即可，公开后会保持时间顺序。</p>${r.timeline.map((t,i)=>`<fieldset class="timeline-editor"><legend>第 ${i+1} 段经历</legend><div class="form-grid">${field(`time-year-${i}`,"年份","","text",t.year,10)}${field(`time-title-${i}`,"阶段标题","","text",t.title,80)}<label class="field full"><span>这段经历的内容</span><textarea name="time-text-${i}" required maxlength="600">${esc(t.text)}</textarea></label></div></fieldset>`).join("")}</div><label class="field full"><span>本次回访补充（选填，填写后追加时间线）</span><textarea name="update" maxlength="600" placeholder="这一阶段有哪些变化？"></textarea></label></div><label class="check"><input type="checkbox" name="followup" ${r.followup?'checked':''}>愿意接受后续站内回访</label><label class="check"><input type="checkbox" name="consent" required>我同意重新审核后公开以上资料。</label><button class="btn" type="submit">保存并重新审核</button><div class="form-message" role="alert"></div></form>`;$('.close',d).onclick=()=>d.close();d.showModal();$('#update-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=$('button[type=submit]',form);b.disabled=true;try{const raw=Object.fromEntries(new FormData(form));const timeline=r.timeline.map((_,i)=>({year:raw[`time-year-${i}`],title:raw[`time-title-${i}`],text:raw[`time-text-${i}`]}));await api(`/records/${r.id}`,'PATCH',{...raw,year:Number(raw.year),timeline,followup:form.elements.followup.checked,consent:true});d.close();await refresh();render();toast('更新已保存，等待重新审核');}catch(e){$('.form-message',form).textContent=e.message;}finally{b.disabled=false;}};
}
async function admin(version) {
  if(!user?.admin){main.innerHTML='<div class="wrap article"><div class="notice">此页面仅管理员可访问。</div></div>';return;}
  main.innerHTML='<div class="wrap article"><p>正在读取审核队列…</p></div>';
  try{const data=await api('/admin/records');if(version!==pageVersion)return;main.innerHTML=`<div class="wrap article">${heading('MODERATION DESK','审核工作台','审核检查隐私泄露、广告和内容完整性。通过审核不代表核验了学历或雇佣关系。')}<div class="notice">不要公开具体学校、公司、姓名、联系方式或可识别他人的信息。请在通过前阅读完整时间线。</div><div class="dashboard-list">${data.records.length?data.records.map(r=>`<article class="dashboard-item"><span class="status-pill">${esc(r.reviewStatus)}</span><h3>${esc(r.alias)} · ${esc(r.role)}</h3><p>${esc(r.year)} 届 / ${esc(r.major)} / ${esc(r.tier)} / ${esc(r.region)} / ${esc(r.degree)}<br>${esc(r.city)} / ${esc(r.status)} / ${esc(r.industry)} / ${esc(r.salary)}</p><p>${esc(r.summary)}</p><p>建议：${esc(r.advice)}</p><div class="timeline">${r.timeline.map(t=>`<div class="timeline-item"><small>${esc(t.year)}</small><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p></div>`).join('')}</div><label class="field"><span>审核意见（退回必填）</span><input id="note-${r.id}" maxlength="300" placeholder="如：请移除具体公司名称"></label><div class="inline-actions"><button class="btn small" data-review="${r.id}" data-status="approved">通过并公开</button><button class="btn light small" data-review="${r.id}" data-status="rejected">退回修改</button></div></article>`).join(''):'<div class="empty">当前没有需要处理的记录。</div>'}</div></div>`;document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/admin/records/${b.dataset.review}`,'POST',{status:b.dataset.status,note:$(`#note-${b.dataset.review}`).value});await refresh();render();toast('审核结果已保存');}catch(e){toast(e.message);b.disabled=false;}});}catch(e){if(version===pageVersion)main.innerHTML=`<div class="wrap article"><div class="notice">${esc(e.message)}</div></div>`;}
}
function article(page) {
 const content={
  voyagers:[ 'THE VOYAGERS','远航者：把经验传下去','你不需要“功成名就”才能帮助别人。真实，就是一份有价值的礼物。',`<div class="policy-cards"><div class="policy-card"><div class="big-number">01</div><h3>留下你的起点</h3><p>记录毕业背景、求职方向和选择，不收集具体学校或公司。</p></div><div class="policy-card"><div class="big-number">02</div><h3>记下沿途的变化</h3><p>毕业后 1、2、5、10 年回来更新。也可以随时补充、修正或撤回。</p></div><div class="policy-card"><div class="big-number">03</div><h3>让后来者少一点迷茫</h3><p>成功、停顿和转向都值得记录。我们不以薪资高低判断贡献价值。</p></div></div><h2>我们如何回访</h2><p>本版提供个人页面的回访到期提醒。未来计划按专业、地区、毕业年份和初始状态分组抽样，邀请自愿参与的远航者回访。站内会分别披露邀请人数、回应人数与样本量，避免将少数人的经历当成所有人的答案。</p><div class="notice">当前没有自动发送回访通知，也没有发放现金奖励。所有回访均可自愿退出。</div><a class="btn" href="#/contribute">成为远航者 ↗</a>`],
  principles:['BUILT ON TRUST','互助，需要清楚的规则','人人为我，我为人人。我们希望让贡献得到认可，也让每一笔费用有明确的用途。',`<h2>现在：免费验证，先积累可信内容</h2><p>当前版本的查询与贡献全部免费，不收取 30 元或 100 元费用，不创建付费订单。30 元、100 元只是最初讨论的价格假设，尚未成为正式定价。</p><h2>未来：按实际价值收费</h2><p>基础分布、样例和样本数量计划保持免费。付费服务若上线，将明确展示覆盖范围、更新时间、服务内容、价格与退款规则。总记录数量不能替代与你相关的信息价值。</p><h2>贡献奖励：根据当期预算与有效贡献</h2><p>未来可能从实际服务收入中安排预算，奖励有效新记录和后续更新。比例与审核标准需正式公布后才能生效。提交信息不形成投资、固定收益或永久分红权利，奖励与邀请新人数量无关。</p><h2>数据质量公开说明</h2><ul><li>虚构示例、本人自述与核验记录分开标注。</li><li>审核只确认内容适合公开，不等于学历、公司和薪资核验。</li><li>自愿提交样本存在选择偏差，不用于宣称某专业真实就业率。</li><li>不因待业、转行、薪资下降或职业中断而拒绝真实经历。</li></ul>`],
  privacy:['YOUR STORY, YOUR CONTROL','隐私说明 · 试运行版','更新日期：2026 年 10 月 23 日。正式运营前，需要由运营主体补全联系方式、处理期限与适用规则。',`<h2>收集哪些信息</h2><p>账号服务保存邮箱、昵称、密码加盐摘要与短期登录会话。职业档案保存学校层次、就读地区、专业大类、学历、毕业年份、城市、行业、岗位、薪资区间、经历和回访选择。公开页面不会包含账号邮箱或用户编号。</p><h2>哪些内容会公开</h2><p>勾选同意并提交后，职业档案经人工审核才公开。学校仅记录层次与地区，昵称代替姓名。即使这样，组合信息仍可能使熟人推断身份；请不要填写具体学校、公司、联系方式或他人的资料。</p><h2>如何更正、撤回与删除</h2><p>登录“我的航程”可更正资料、补充回访、导出本人资料、立即撤回公开记录，或永久删除记录与账号。更新重新进入审核队列。撤回不等于删除，撤回记录只对本人及审核管理员可见。</p><h2>如何保存</h2><p>完整服务把资料保存在运营方控制的 SQLite 数据库中，与开源代码分离。密码不会明文保存。会话有效期 7 天，到期后不可使用。当前版本未对接广告、支付、邮件发送或第三方统计。</p><h2>演示版本</h2><p>静态演示只展示虚构案例，不提供真实账号服务。演示草稿仅存于当前浏览器，可在贡献页面点击“清除草稿”删除。请勿在演示草稿中填写真实信息。</p><h2>试运行边界</h2><p>本版尚未提供邮箱验证和密码找回。正式公开收集真实资料前，运营方需配置 HTTPS、备份与删除制度、运营联系方式，并完成隐私与业务资质审查。不同部署方应更新本说明，不能照搬后直接宣称合规。</p>`],
  about:['ABOUT ACRIS','每个人，都可以成为一块路标','Acris 是一个面向毕业生的职业路径互助资料库，让经验可以被下一届看见。',`<h2>从“我的专业能做什么”开始</h2><p>我们关注相近背景的人如何做选择，以及几年后的生活发生了什么变化。学校层次和地区作为筛选条件，不提供具体学校的毕业生追踪名单。</p><h2>代码开放，个人数据独立</h2><p>项目使用 MIT 许可证开放源代码，允许学习、修改和部署。真实用户资料、数据库、密码与服务密钥不在开源范围内。仓库中的案例均为虚构示例。</p><p><a class="btn light" href="https://github.com/brushurteath/Acris" target="_blank" rel="noopener noreferrer">查看 GitHub 项目 ↗</a></p><h2>当前版本</h2><p>v0.1.0：职业路径筛选、详情时间线、注册登录、贡献、回访、审核、更正、撤回、导出和删除。付费与奖励尚未接入；域名 Acris.com 尚未购买或绑定。</p>`]
 };const c=content[page];main.innerHTML=`<div class="wrap article">${heading(c[0],c[1],c[2])}${c[3]}</div>`;
}
async function refresh(){if(live){const data=await api('/records');records=data.records;}}
function render(){galaxy?.destroy();galaxy=null;const version=++pageVersion;const raw=location.hash.slice(1)||'/';const [path,query='']=raw.split('?');const page=path.slice(1);if(!page)home();else if(page==='explore')explore(new URLSearchParams(query));else if(page==='login')login();else if(page==='contribute')contribution();else if(page==='account')account(version);else if(page==='admin')admin(version);else if(['voyagers','principles','privacy','about'].includes(page))article(page);else main.innerHTML='<div class="wrap article"><h1>这条航线还没有开通</h1><a class="btn" href="#/">回到首页</a></div>';document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));}
async function init(){try{const response=await fetch('/api/health',{signal:AbortSignal.timeout(2500)});if(response.ok&&(response.headers.get('content-type')||'').includes('application/json')){const health=await response.json();live=health.service==='acris';}}catch{}if(live){try{const data=await api('/me');user=data.user;csrf=data.csrf||'';await refresh();}catch(e){main.innerHTML=`<div class="wrap article"><div class="notice">数据库服务无法读取：${esc(e.message)} 请刷新重试。</div></div>`;return;}}else records=examples;$('#mode-banner').textContent=live?'试运行 · 真实贡献须审核后公开 · 当前免费，无支付或现金奖励':'演示预览 · 所有职业案例均为虚构 · 账号、审核与数据库功能请运行完整开源项目';$('#mode-banner').classList.toggle('live',live);authNav();render();}
$('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();});init();
